set)
  [ "$#" -eq 4 ] && [ "$3" = --why ] || die 'usage: set KEY VALUE --why TEXT'
  setting "$1" "$2"; reason_check "$4"
  {
    header; printf '%s\n' 'BEGIN IMMEDIATE;'; input_table
    policy_sql "$1" "$2" "$4"
    printf '%s\n' "CREATE TEMP TABLE report AS SELECT 'Policy receipt '||id||': '||state AS result FROM head;" 'COMMIT;' 'SELECT result FROM report;'
  } | sqlite3 "$DB"
  ;;

function chart(future) {
  const root = $("history-chart");
  root.replaceChildren();
  const projected = future ? [state, ...future.events.filter(e => e.kind === "tick").map(e => e.state)] : [];
  const past = history.map(e => e.state);
  const first = past.length ? past[0].day : state.day;
  const last = Math.max(first + 1, projected.length ? projected[projected.length - 1].day : state.day);
  const x = day => 36 + 548 * (day - first) / (last - first);
  const y = (value, maximum) => 214 - 186 * value / maximum;
  for (const fraction of [0, .25, .5, .75, 1]) {
    const yy = y(fraction, 1);
    root.append(svgElement("line", {x1:36, y1:yy, x2:584, y2:yy, class:"chart-grid"}));
    root.append(svgElement("text", {x:26, y:yy + 4, "text-anchor":"end", class:"chart-label"}, fraction * 24));
  }
  const days = [...new Set([first, state.day, last])];
  for (const day of days) root.append(svgElement("text",
    {x:x(day), y:240, "text-anchor":"middle", class:"chart-label"}, "day " + day));
  if (future) root.append(svgElement("line", {x1:x(state.day), y1:20, x2:x(state.day), y2:215,
    stroke:"#7c816b", "stroke-dasharray":"2 4"}));
  for (const [key, maximum, color] of [["water",24,"#8bbbbe"],["food",24,"#dfb36c"],["soil",10,"#9ab581"]]) {
    const line = (points, isFuture) => {
      if (!points.length) return;
      const d = points.map((s, i) => (i ? "L" : "M") + x(s.day) + " " + y(s[key], maximum)).join(" ");
      root.append(svgElement("path", {d, stroke:color, class:"chart-line" + (isFuture ? " chart-future" : "")}));
      if (points.length === 1) root.append(svgElement("circle",
        {cx:x(points[0].day),cy:y(points[0][key],maximum),r:3,fill:color}));
    };
    line(past, false); line(projected, true);
  }
